32	AgentRuntime load_agent_runtime(AppConfig* config)
33	{
34	    AgentSettings settings;
35	    settings.enabled       = configured_true(config, "enabled");
36	    settings.cloud_consent = configured_true(config, "cloud_consent");
37	    if (config != nullptr) {
38	        settings.provider = config->get(kSection, "provider");
39	        settings.model    = config->get(kSection, "model");
40	    }
41	    settings.api_key = load_provider_api_key(config, settings.provider.empty() ? "openai" : settings.provider);
42	    ProviderListeners listeners;
43	    // Refused tool calls never reach a card or the activity list; the log is
44	    // where a wrong call can be read afterwards.
45	    listeners.refusal = [](const std::string& tool, const std::string& arguments, const std::string& code) {
46	        BOOST_LOG_TRIVIAL(warning) << "Agent tool call refused (" << code << "): " << tool << " " << arguments.substr(0, 1024);
47	    };
48	    AgentRuntime runtime = resolve_agent_runtime(settings, agent_endpoint_override(), &make_openai_http_transport, std::move(listeners));
49	    runtime.setup        = make_agent_setup(config);
50	    return runtime;
51	}
