53	AgentSetupServicePtr make_agent_setup(AppConfig* config)
54	{
55	    // Committing is the only part of setup that touches the machine, so it
56	    // lives here rather than in the GUI-free probe. Reaching this point means
57	    // the user read what the dock says about the provider billing them and
58	    // about the key staying on this machine, and chose to continue: that is
59	    // the cloud consent load_agent_runtime() requires on the next launch.
60	    auto commit = [config](const SetupCredentials& credentials) {
61	        if (config == nullptr || credentials.provider.empty() || credentials.api_key.empty())
62	            return false;
63	        config->set(kSection, api_key_item_for(credentials.provider), credentials.api_key);
64	        config->set(kSection, "provider", credentials.provider);
65	        config->set(kSection, "enabled", "true");
66	        config->set(kSection, "cloud_consent", "true");
67	        if (!credentials.model.empty())
68	            config->set(kSection, "model", credentials.model);
69	        // Written now, not at the next routine save, so a crash after setup
70	        // does not lose a key the user was just told is stored.
71	        config->save();
72	        return true;
73	    };
74	    return std::make_shared<ProviderKeySetup>(&make_openai_http_transport, std::move(commit), agent_endpoint_override());
75	}
