 10	// The probe deliberately carries no project. A provider the user has not
 11	// chosen yet must not receive their workspace merely to prove that a key
 12	// works, so the request is a fixed sentence with an empty snapshot.
 13	AgentRequest probe_request()
 14	{
 15	    AgentRequest request;
 16	    request.request_id = "setup-key-check";
 17	    request.user_text  = "Reply with the single word: ready.";
 18	    return request;
 19	}
 20	
 21	} // namespace
 22	
 23	bool setup_provider_supported(const std::string& provider) { return profile_for(provider) != nullptr; }
 24	
 25	ProviderKeySetup::ProviderKeySetup(TransportFactory transport,
 26	                                   CommitFn         commit,
 27	                                   std::string      endpoint_override,
 28	                                   Clock            clock)
 29	    : m_transport_factory(std::move(transport)), m_commit(std::move(commit)),
 30	      m_endpoint_override(std::move(endpoint_override)), m_clock(std::move(clock))
 31	{
 32	    if (!m_clock)
 33	        m_clock = []() { return std::chrono::steady_clock::now(); };
 34	}
 35	
 36	ProviderKeySetup::~ProviderKeySetup() = default;
 37	
 38	bool ProviderKeySetup::start_check(const SetupCredentials& credentials)
 39	{
 40	    if (busy() || credentials.api_key.empty() || !setup_provider_supported(credentials.provider))
 41	        return false;
 42	
 43	    const std::string endpoint = credentials.endpoint.empty() ? m_endpoint_override : credentials.endpoint;
 44	    AgentServicePtr   candidate = make_provider_agent(*profile_for(credentials.provider), credentials.api_key, credentials.model,
 45	                                                      endpoint, m_transport_factory());
 46	    if (!candidate->ready())
 47	        return false;
 48	
 49	    m_started = m_clock();
 50	    if (!candidate->start(probe_request()))
 51	        return false;
 52	    m_candidate = std::move(candidate);
 53	    return true;
 54	}
 55	
 56	void ProviderKeySetup::cancel()
 57	{
 58	    if (m_candidate)
 59	        m_candidate->cancel();
 60	    m_candidate.reset();
 61	}
 62	
 63	std::optional<SetupOutcome> ProviderKeySetup::poll()
 64	{
 65	    if (!m_candidate)
 66	        return std::nullopt;
 67	
 68	    while (const std::optional<AgentEvent> event = m_candidate->poll()) {
 69	        switch (event->kind) {
 70	        case AgentEventKind::TextDelta:
 71	            break; // What it says is irrelevant; that it answers is the test.
 72	        case AgentEventKind::ToolCall:
 73	        case AgentEventKind::Completed:
 74	            // Either way the provider accepted the credentials and replied.
 75	            return finish_ok();
 76	        case AgentEventKind::Failed: {
 77	            SetupOutcome outcome;
 78	            outcome.error =
 79	                event->error.value_or(AgentError{"setup_failed", "The provider did not answer.", true});
 80	            outcome.elapsed_ms = elapsed_ms();
 81	            cancel();
 82	            return outcome;
 83	        }
 84	        }
 85	    }
 86	    return std::nullopt;
 87	}
 88	
 89	bool ProviderKeySetup::commit(const SetupCredentials& credentials)
 90	{
 91	    return m_commit && m_commit(credentials);
 92	}
 93	
 94	int ProviderKeySetup::elapsed_ms() const
 95	{
 96	    return static_cast<int>(std::chrono::duration_cast<std::chrono::milliseconds>(m_clock() - m_started).count());
 97	}
 98	
 99	SetupOutcome ProviderKeySetup::finish_ok()
100	{
101	    SetupOutcome outcome;
102	    outcome.ok         = true;
103	    outcome.elapsed_ms = elapsed_ms();
104	    // Drop the probe turn so the verified service is handed over idle, with
105	    // no partial response left for the user's first real message to inherit.
106	    m_candidate->cancel();
107	    outcome.service = std::move(m_candidate);
108	    m_candidate.reset();
109	    return outcome;
110	}
