 14	namespace Slic3r::GUI::JusPrin::Agent {
 15	
 16	// The wire format a provider speaks; one codec per family.
 17	enum class ProviderFamily { Responses, Anthropic };
 18	
 19	// How the API key travels: `Authorization: Bearer <key>`, or `x-api-key: <key>`.
 20	enum class AuthStyle { Bearer, ApiKeyHeader };
 21	
 22	struct ProviderProfile
 23	{
 24	    std::string    id;
 25	    ProviderFamily family{ProviderFamily::Responses};
 26	    std::string    endpoint;
 27	    AuthStyle      auth{AuthStyle::Bearer};
 28	    // The provider's default; a configured model replaces it in the copy the
 29	    // agent is built with.
 30	    std::string    model;
 31	    // In the error text, as in "The OpenAI API key was rejected".
 32	    std::string    display_name;
 33	    // Sent on every request, after the credential.
 34	    std::vector<AgentHttpHeader> headers;
 35	    // The most output tokens one response may use, for a family that
 36	    // requires the number (Anthropic); 0 where none is sent.
 37	    unsigned       max_tokens{0};
 38	};
 39	
 40	// Every provider this build can talk to, in the order setup lists them.
 41	inline const std::vector<ProviderProfile>& provider_profiles()
 42	{
 43	    static const std::vector<ProviderProfile> rows{
 44	        {"openai", ProviderFamily::Responses, "https://api.openai.com/v1/responses", AuthStyle::Bearer, "gpt-5.4-mini", "OpenAI", {}, 0},
 45	        // OpenRouter serves the Responses API. The default is the model the
 46	        // OpenAI row uses, so the behaviour is the one already evaluated.
 47	        // X-Title names the app in OpenRouter's usage pages. OpenRouter
 48	        // also reads HTTP-Referer, the app's website, to give it a page of
 49	        // its own; this build has no website constant to send, so it sends
 50	        // none.
 51	        {"openrouter", ProviderFamily::Responses, "https://openrouter.ai/api/v1/responses", AuthStyle::Bearer,
 52	         "openai/gpt-5.4-mini", "OpenRouter", {{"X-Title", "JusPrin"}}, 0},
 53	        // The Messages API. max_tokens is required there and also bounds the
 54	        // model's thinking, which this model cannot turn off; 64000 is the
 55	        // value Anthropic suggests for streaming requests.
 56	        {"anthropic", ProviderFamily::Anthropic, "https://api.anthropic.com/v1/messages", AuthStyle::ApiKeyHeader,
 57	         "claude-opus-5-5", "Anthropic", {{"anthropic-version", "2023-06-01"}}, 64000},
 58	    };
 59	    return rows;
 60	}
 61	
 62	// The row for a provider id, or null when this build has none.
 63	inline const ProviderProfile* profile_for(const std::string& id)
 64	{
 65	    for (const ProviderProfile& profile : provider_profiles())
 66	        if (profile.id == id)
 67	            return &profile;
 68	    return nullptr;
 69	}
