 29	AgentServicePtr make_provider_agent(const ProviderProfile&               profile,
 30	                                    const std::string&                   api_key,
 31	                                    const std::string&                   model,
 32	                                    const std::string&                   endpoint,
 33	                                    std::unique_ptr<IAgentHttpTransport> transport,
 34	                                    ProviderListeners                    listeners)
 35	{
 36	    ProviderAgentConfig config;
 37	    config.profile = profile;
 38	    if (!model.empty())
 39	        config.profile.model = model;
 40	    if (!endpoint.empty())
 41	        config.profile.endpoint = endpoint;
 42	    config.api_key          = api_key;
 43	    config.usage_listener   = std::move(listeners.usage);
 44	    config.refusal_listener = std::move(listeners.refusal);
 45	    return std::make_unique<ProviderAgent>(std::move(config), codec_for(profile.family), std::move(transport));
