 54	
 55	AgentRuntime resolve_agent_runtime(const AgentSettings&                                         settings,
 56	                                   const std::string&                                           endpoint_override,
 57	                                   const std::function<std::unique_ptr<IAgentHttpTransport>()>& transport,
 58	                                   ProviderListeners                                            listeners)
 59	{
 60	    AgentRuntime runtime;
 61	    runtime.provider = settings.provider.empty() ? "openai" : settings.provider;
 62	    if (!settings.enabled) {
 63	        runtime.unavailable_reason = "The Agent is not enabled.";
 64	        return runtime;
 65	    }
 66	    const ProviderProfile* profile = profile_for(runtime.provider);
 67	    if (profile == nullptr) {
 68	        runtime.unavailable_reason = "The configured Agent provider is not supported.";
 69	        return runtime;
 70	    }
 71	    if (!settings.cloud_consent) {
 72	        runtime.unavailable_reason = "Cloud Agent access requires explicit consent.";
 73	        return runtime;
 74	    }
 75	    if (settings.api_key.empty()) {
 76	        runtime.unavailable_reason = "No " + profile->display_name + " API key is configured.";
 77	        return runtime;
 78	    }
 79	    runtime.service = make_provider_agent(*profile, settings.api_key, settings.model, endpoint_override, transport(),
 80	                                          std::move(listeners));
 81	    runtime.availability = runtime.service->ready() ? AgentAvailability::Ready : AgentAvailability::Unavailable;
 82	    if (runtime.availability == AgentAvailability::Unavailable)
 83	        runtime.unavailable_reason = "The " + profile->display_name + " Agent could not be initialized.";
 84	    return runtime;
 85	}
