 23	// What one request cost, as the provider reported it. `cached_input` is the
 24	// part of `input` the provider served from its prompt cache, and it is the
 25	// number the tool-loading decision rests on: a tools array that stays
 26	// byte-identical across a chat should be cached from the second request on,
 27	// and a catalog that is not being cached is paid for in full every turn.
 28	struct AgentUsage
 29	{
 30	    std::uint64_t input{0};
 31	    std::uint64_t cached_input{0};
 32	    // The part of `input` written to the prompt cache by this request, where
 33	    // the provider reports it separately (Anthropic); 0 elsewhere.
 34	    std::uint64_t cache_creation{0};
 35	    std::uint64_t output{0};
 36	    std::uint64_t total{0};
