 41	// The app's data beside the person's words, in a tag of its own. JSON keeps
 42	// "<" only inside strings, where "<\/" means the same thing, so a project
 43	// name cannot close the tag early. The same block for every provider: the
 44	// instructions name the tags.
 45	inline std::string tagged_block(const char* tag, const std::string& json_text)
 46	{
 47	    std::string escaped;
 48	    escaped.reserve(json_text.size());
 49	    for (std::size_t i = 0; i < json_text.size(); ++i) {
 50	        escaped += json_text[i];
 51	        if (json_text[i] == '<' && i + 1 < json_text.size() && json_text[i + 1] == '/')
 52	            escaped += '\\';
 53	    }
 54	    return std::string("<") + tag + ">\n" + escaped + "\n</" + tag + ">";
 55	}
