116	    // This turn's user message; empty when the turn has none to send.
117	    std::vector<TurnContentPart>          user_content;
118	    std::vector<TurnStep>                 steps;
119	    // Skills fired for the turn's first request, sent after its user
120	    // message. Every request records the skills it was the first to carry,
121	    // here or in its last step, and the codec decides what a later request
122	    // makes of them: the Responses codec sends each set on its own request
123	    // only, and the Anthropic codec keeps it in place, because removing an
124	    // earlier message is an edit that invalidates the thinking after it.
125	    std::vector<AgentSkillUse>            opening_once;
126	};
