 11	
 12	json text_part(std::string text) { return json{{"type", "input_text"}, {"text", std::move(text)}}; }
 13	
 14	std::string data_url(const std::string& mime, const std::string& base64) { return "data:" + mime + ";base64," + base64; }
 15	
 16	bool has_closed_required_objects(const json& schema)
 17	{
 18	    if (schema.value("type", json()) == "object") {
 19	        if (schema.value("additionalProperties", json()) != false)
 20	            return false;
 21	        const auto properties = schema.value("properties", json::object());
 22	        const auto required = schema.value("required", json::array());
 23	        for (const auto& property : properties.items())
 24	            if (std::find(required.begin(), required.end(), property.key()) == required.end() ||
 25	                !has_closed_required_objects(property.value()))
 26	                return false;
 27	    }
 28	    return !schema.contains("items") || has_closed_required_objects(schema["items"]);
 29	}
 30	
 31	json tools_json(const std::vector<OfferedTool>& tools)
 32	{
 33	    json items = json::array();
 34	    for (const OfferedTool& tool : tools)
 35	        items.push_back(json{{"type", "function"},
 36	                             {"name", tool.definition->name},
 37	                             {"description", tool.description},
 38	                             // OpenAI strict mode cannot express optional
 39	                             // fields or dynamic maps. Preserve the registry
 40	                             // schema; native validation still owns acceptance.
 41	                             {"strict", has_closed_required_objects(tool.definition->input_schema)},
 42	                             {"parameters", tool.definition->input_schema}});
 43	    return items;
 44	}
 45	
 46	json user_message(const std::vector<TurnContentPart>& parts)
 47	{
 48	    json content = json::array();
 49	    for (const TurnContentPart& part : parts) {
 50	        switch (part.kind) {
 51	        case TurnContentPart::Kind::Text: content.push_back(text_part(part.text)); break;
 52	        case TurnContentPart::Kind::Image:
 53	            content.push_back(json{{"type", "input_image"}, {"image_url", data_url(part.mime, part.base64)}});
 54	            break;
 55	        case TurnContentPart::Kind::Pdf:
 56	            content.push_back(json{{"type", "input_file"}, {"filename", part.filename}, {"file_data", data_url(part.mime, part.base64)}});
 57	            break;
 58	        }
 59	    }
 60	    return json{{"role", "user"}, {"content", std::move(content)}};
 61	}
 62	
 63	json input_items(const TurnTranscript& transcript, RequestKind kind)
 64	{
 65	    json input = json::array();
 66	    for (const auto& message : transcript.opening) {
 67	        if (message.call_id.empty()) {
 68	            if (message.issue_context.empty())
 69	                input.push_back(json{{"role", message.role}, {"content", message.text}});
 70	            else
 71	                input.push_back(json{{"role", message.role},
 72	                                     {"content", json::array({text_part(message.text),
 73	                                                              text_part(tagged_block("print_issue", message.issue_context))})}});
 74	            continue;
 75	        }
 76	        // A call from an earlier turn, replayed for this stateless request.
 77	        // Its call_id pairs it with its output. The item id the service gave
 78	        // the call is not sent: with store:false it names nothing kept.
 79	        input.push_back(json{{"type", "function_call"}, {"call_id", message.call_id}, {"name", message.tool},
 80	                             {"arguments", message.arguments_json}});
 81	        input.push_back(json{{"type", "function_call_output"}, {"call_id", message.call_id}, {"output", message.output_json}});
 82	    }
 83	    if (kind == RequestKind::Reply && !transcript.user_content.empty())
 84	        input.push_back(user_message(transcript.user_content));
 85	    for (const TurnStep& step : transcript.steps) {
 86	        // The response's own items, reasoning included, exactly as sent.
 87	        input.insert(input.end(), step.assistant_turn.begin(), step.assistant_turn.end());
 88	        for (const TurnStepResult& result : step.results)
 89	            input.push_back(json{{"type", "function_call_output"}, {"call_id", result.call_id}, {"output", result.output_json}});
 90	        // A function result is text only; the pictures follow the results as
 91	        // image inputs.
 92	        for (const TurnStepResult& result : step.results)
 93	            if (result.image)
 94	                input.push_back(json{{"role", "user"},
 95	                                     {"content", json::array({json{{"type", "input_text"}, {"text", "The image returned by call " + result.call_id + "."}},
 96	                                                              json{{"type", "input_image"},
 97	                                                                   {"image_url", data_url(result.image->mime_type, result.image->base64)}}})}});
 98	    }
 99	    // A fired skill as the request's last items: its picture, as an image
100	    // input of its own, then its text in the app's voice.
101	    for (const AgentSkillUse& skill : newest_once(transcript)) {
102	        if (skill.picture)
103	            input.push_back(json{{"role", "user"},
104	                                 {"content", json::array({json{{"type", "input_image"},
105	                                                               {"image_url", data_url(skill.picture->mime_type, skill.picture->base64)}}})}});
106	        input.push_back(json{{"role", "developer"}, {"content", skill.text}});
107	    }
108	    return input;
109	}
