113	ProviderRequest ResponsesCodec::build(const TurnTranscript& transcript, const ProviderProfile& profile, RequestKind kind) const
114	{
115	    ProviderRequest request;
116	    request.headers.push_back({"Idempotency-Key", transcript.request_id + "-request-" + std::to_string(transcript.request_sequence)});
117	    json input = input_items(transcript, kind);
118	    if (kind == RequestKind::ConversationTitle) {
119	        request.body = json{{"model", profile.model}, {"store", false}, {"stream", true},
120	                            {"instructions", kConversationTitleInstructions}, {"input", std::move(input)}};
121	        return request;
122	    }
123	    // Every session's instructions are written by its page and arrive in the
124	    // session profile, the project assistant's included
125	    // (AgentUI/src/projectInstructions.ts); this codec adds no words of its
126	    // own. The text is the same on every request of a conversation, which the
127	    // provider's prompt cache depends on. A response may hold several calls:
128	    // a read and the change it does not depend on belong in one step, and
129	    // some models send several whatever this says (ProviderAgent runs them
130	    // all, in order).
131	    request.body = json{{"model", profile.model}, {"store", false}, {"stream", true}, {"parallel_tool_calls", true},
132	                        {"instructions", transcript.instructions}, {"tools", tools_json(transcript.tools)}, {"input", std::move(input)}};
133	    return request;
134	}
135	
136	std::vector<StreamEvent> ResponsesCodec::parse(const std::string& payload)
137	{
138	    std::vector<StreamEvent> events;
139	    const auto               push = [&events](StreamEvent::Kind kind) -> StreamEvent& {
140	        events.push_back(StreamEvent{});
141	        events.back().kind = kind;
142	        return events.back();
143	    };
144	    const json event = json::parse(payload, nullptr, false);
145	    if (!event.is_object()) {
146	        push(StreamEvent::Kind::Failed).error = {"malformed_response", "The Agent service returned an unreadable streaming response.", false};
147	        return events;
148	    }
149	    const std::string type = event.value("type", "");
150	    if (type == "response.output_text.delta" && event.contains("delta") && event["delta"].is_string()) {
151	        push(StreamEvent::Kind::TextDelta).text = event["delta"].get<std::string>();
152	    } else if (type == "response.completed" && event.contains("response")) {
153	        if (m_completed)
154	            return events;
155	        m_completed = true;
156	        const json& response = event["response"];
157	        if (!response.is_object() || !response.contains("output") || !response["output"].is_array()) {
158	            push(StreamEvent::Kind::Failed).error = {"malformed_response", "The Agent service response did not contain valid output.", false};
159	            return events;
160	        }
161	        StreamEvent& complete = push(StreamEvent::Kind::TurnComplete);
162	        complete.assistant_turn = response["output"];
163	        for (const json& item : complete.assistant_turn)
164	            if (item.is_object() && item.value("type", "") == "function_call")
165	                complete.calls.push_back({item.value("call_id", ""), item.value("name", ""), item.value("arguments", "{}")});
166	        if (response.contains("usage") && response["usage"].is_object()) {
167	            const json& usage = response["usage"];
168	            AgentUsage   reported;
169	            reported.input  = usage.value("input_tokens", std::uint64_t{0});
170	            reported.output = usage.value("output_tokens", std::uint64_t{0});
171	            reported.total  = usage.value("total_tokens", std::uint64_t{0});
172	            if (usage.contains("input_tokens_details") && usage["input_tokens_details"].is_object())
173	                reported.cached_input = usage["input_tokens_details"].value("cached_tokens", std::uint64_t{0});
174	            complete.usage = reported;
175	        }
176	    } else if (type == "response.incomplete") {
177	        push(StreamEvent::Kind::Incomplete);
178	    } else if (type == "response.failed" || type == "error") {
179	        push(StreamEvent::Kind::Failed).error = {"agent_service_error", "The Agent service could not complete the response.", true};
180	    }
181	    return events;
182	}
