119	    18	// What the intent and plan leave out rather than send empty: an unset field,
120	    19	// an empty list, a false truncated flag.
121	    20	void drop_empty(json& value)
122	    21	{
123	    22	    if (!value.is_object() && !value.is_array())
124	    23	        return;
125	    24	    for (json& child : value)
126	    25	        drop_empty(child);
127	    26	    if (!value.is_object())
128	    27	        return;
129	    28	    for (auto it = value.begin(); it != value.end();) {
130	    29	        const bool empty = it->is_null() || (it->is_string() && it->get_ref<const std::string&>().empty()) ||
131	    30	                           ((it->is_array() || it->is_object()) && it->empty()) ||
132	    31	                           (it.key() == "truncated" && *it == false);
133	    32	        it = empty ? value.erase(it) : std::next(it);
134	    33	    }
135	    34	}
