137	    36	json workspace_json(const AgentRequest& request)
138	    37	{
139	    38	    const Workspace::WorkspaceSnapshot& workspace = request.workspace;
140	    39	    json plates = json::array();
141	    40	    for (const auto& plate : workspace.plates) {
142	    41	        json objects = json::array();
143	    42	        for (const auto& object : plate.objects)
144	    43	            objects.push_back(json{{"id", std::to_string(object.id.value())}, {"name", object.name},
145	    44	                                   {"instances", object.instances.size()}});
146	    45	        json entry{{"id", std::to_string(plate.id.value())}, {"name", plate.name},
147	    46	                   {"active", plate.active}, {"sliced", plate.sliced}, {"objects", std::move(objects)}};
148	    47	        // In printer_setup's name and plate_layout's values, so a filament
149	    48	        // the plate cannot take is visible before anything is sliced.
150	    49	        if (!plate.bed_type.empty())
151	    50	            entry["plateType"] = plate.bed_type;
152	    51	        // Why its last slice did not succeed, whoever asked for that slice.
153	    52	        if (plate.slice_failure)
154	    53	            entry["sliceFailure"] = slice_failure_result(*plate.slice_failure);
155	    54	        // What its current slice warned about, whoever sliced it.
156	    55	        if (plate.slice_warnings)
157	    56	            entry["sliceWarnings"] = slice_warnings_result(*plate.slice_warnings);
158	    57	        plates.push_back(std::move(entry));
159	    58	    }
160	    59	    json selected = json::array();
161	    60	    for (const auto id : workspace.selected_objects)
162	    61	        selected.push_back(std::to_string(id.value()));
163	    62	    json result{{"sessionId", std::to_string(workspace.session.value())},
164	    63	                {"revision", workspace.revision},
165	    64	                {"projectName", workspace.setup.project_name},
166	    65	                {"printerPreset", workspace.setup.printer_preset},
167	    66	                {"filamentPreset", workspace.setup.filament_preset},
168	    67	                {"selectedObjectIds", std::move(selected)},
169	    68	                {"plates", std::move(plates)}};
170	    69	    if (!workspace.setup.process_preset.empty())
171	    70	        result["processPreset"] = workspace.setup.process_preset;
172	    71	    // The model's own notes, in the shapes workspace_inspect's intent and plan
173	    72	    // sections return, less their timestamps: on the next turn it reads what
174	    73	    // it recorded without spending a call on it.
175	    74	    json intent = intent_section_result(request.intent);
176	    75	    intent["setupTitle"] = request.setup_title;
177	    76	    for (json& field : intent["fields"])
178	    77	        field.erase("updatedAt");
179	    78	    drop_empty(intent);
180	    79	    if (request.setup_unchecked_change)
181	    80	        intent["setupUncheckedChange"] = true;
182	    81	    if (!intent.empty())
183	    82	        result["intent"] = std::move(intent);
184	    83	    const json full_plan = plan_section_result(request.plan);
185	    84	    json plan{{"headline", full_plan["headline"]}, {"decisions", full_plan["decisions"]},
186	    85	              {"assumptions", full_plan["assumptions"]}, {"truncated", full_plan["truncated"]}};
187	    86	    drop_empty(plan);
188	    87	    // Whether the plan still holds, and the edit that put it in doubt.
189	    88	    if (!plan.empty()) {
190	    89	        plan["validity"] = full_plan["validity"];
191	    90	        if (!request.plan.invalidated_by.empty())
192	    91	            plan["invalidatedBy"] = full_plan["invalidatedBy"];
193	    92	        result["plan"] = std::move(plan);
194	    93	    }
195	    94	    return result;
196	    95	}
