198	    97	bool available_in_app(const ToolDefinition& definition, bool allow_import, bool skills_listed,
199	    98	                      const std::vector<std::string>& session_tools)
200	    99	{
201	   100	    // A session with a subject of its own offers exactly the tools it names,
202	   101	    // and those may be its own rather than the app's.
203	   102	    if (!session_tools.empty())
204	   103	        return std::find(session_tools.begin(), session_tools.end(), definition.name) != session_tools.end() &&
205	   104	               (has_exposure(definition.exposure, ToolExposure::InApp) || has_exposure(definition.exposure, ToolExposure::Printer));
206	   105	    return has_exposure(definition.exposure, ToolExposure::InApp) &&
207	   106	           (definition.availability == ToolAvailability::Always ||
208	   107	            (definition.availability == ToolAvailability::ImportableAttachment && allow_import) ||
209	   108	            (definition.availability == ToolAvailability::SkillIndex && skills_listed));
210	   109	}
