212	   111	// The tools this turn offers, in the registry's order.
213	   112	std::vector<OfferedTool> offered_tools(const AgentRequest& request)
214	   113	{
215	   114	    const bool allow_import = std::any_of(request.attachments.begin(), request.attachments.end(),
216	   115	                                          [](const AgentAttachmentContext& attachment) { return attachment.importable; });
217	   116	    std::vector<OfferedTool> tools;
218	   117	    for (const ToolDefinition& definition : ToolRegistry::instance().definitions()) {
219	   118	        if (!available_in_app(definition, allow_import, !request.skill_index.empty(), request.session.tool_names))
220	   119	            continue;
221	   120	        // skill_read carries the list it reads from, as one line per skill.
222	   121	        std::string description = definition.description;
223	   122	        if (definition.handler == ToolHandler::SkillRead) {
224	   123	            description += "\n\nSkills:";
225	   124	            for (const AgentSkill& skill : request.skill_index)
226	   125	                description += "\n- " + skill.name + ": " + skill.description;
227	   126	        }
228	   127	        tools.push_back(OfferedTool{&definition, std::move(description)});
229	   128	    }
230	   129	    return tools;
231	   130	}
