233	   132	// The skills to send with one request. A skill that yields to another fired
234	   133	// for the same request is left out.
235	   134	std::vector<AgentSkillUse> skills_to_send(const std::vector<AgentSkillUse>& skills)
236	   135	{
237	   136	    std::vector<AgentSkillUse> sent;
238	   137	    for (const AgentSkillUse& skill : skills) {
239	   138	        const bool yields = std::any_of(skills.begin(), skills.end(), [&skill](const AgentSkillUse& other) {
240	   139	            return std::find(skill.yields_to.begin(), skill.yields_to.end(), other.trigger) != skill.yields_to.end();
241	   140	        });
242	   141	        if (!yields)
243	   142	            sent.push_back(skill);
244	   143	    }
245	   144	    return sent;
246	   145	}
