274	   173	void ProviderAgent::begin_transcript(const AgentRequest& request)
275	   174	{
276	   175	    m_transcript = TurnTranscript{};
277	   176	    m_transcript.request_id   = request.request_id;
278	   177	    m_transcript.instructions = request.session.instructions;
279	   178	    m_transcript.opening      = request.conversation;
280	   179	    if (request.purpose == AgentRequest::Purpose::ConversationTitle)
281	   180	        return;
282	   181	    m_transcript.tools = offered_tools(request);
283	   182	    m_transcript.opening_once = skills_to_send(request.skills);
284	   183	    // A turn the app started, after one of its own notes: nothing was said,
285	   184	    // and an empty user message would read as the person saying nothing.
286	   185	    if (request.user_text.empty() && request.issue_context.empty() && request.attachments.empty() &&
287	   186	        !request.session.include_workspace)
288	   187	        return;
289	   188	
290	   189	    // One part per kind of content: the person's words exactly as typed, then
291	   190	    // the app's data, each in its own tag, then the attachments.
292	   191	    std::vector<TurnContentPart>& content = m_transcript.user_content;
293	   192	    const auto text = [&content](std::string value) {
294	   193	        TurnContentPart part;
295	   194	        part.text = std::move(value);
296	   195	        content.push_back(std::move(part));
297	   196	    };
298	   197	    if (!request.user_text.empty())
299	   198	        text(request.user_text);
300	   199	    if (!request.issue_context.empty())
301	   200	        text(tagged_block("print_issue", request.issue_context));
302	   201	    if (request.session.include_workspace)
303	   202	        text(tagged_block("workspace", workspace_json(request).dump()));
304	   203	    std::ostringstream attachments;
305	   204	    for (const auto& attachment : request.attachments) {
306	   205	        if (attachments.tellp() > 0)
307	   206	            attachments << "\n";
308	   207	        attachments << "Attachment " << attachment.id << ": " << attachment.name << " [" << attachment.kind << "]";
309	   208	        if (!attachment.summary.empty())
310	   209	            attachments << " — " << attachment.summary;
311	   210	        if (!attachment.text.empty())
312	   211	            attachments << "\n<attachment id=\"" << attachment.id << "\">\n" << attachment.text << "\n</attachment>";
313	   212	    }
314	   213	    if (attachments.tellp() > 0)
315	   214	        text(attachments.str());
316	   215	    for (const auto& attachment : request.attachments) {
317	   216	        if (attachment.bytes.empty())
318	   217	            continue;
319	   218	        TurnContentPart part;
320	   219	        part.mime   = attachment.mime.empty() ? "application/octet-stream" : attachment.mime;
321	   220	        part.base64 = base64_encode(attachment.bytes);
322	   221	        if (attachment.kind == "image") {
323	   222	            part.kind = TurnContentPart::Kind::Image;
324	   223	        } else if (attachment.kind == "pdf") {
325	   224	            part.kind     = TurnContentPart::Kind::Pdf;
326	   225	            part.filename = attachment.name;
327	   226	        } else {
328	   227	            continue;
329	   228	        }
330	   229	        content.push_back(std::move(part));
331	   230	    }
332	   231	}
