378	   277	bool ProviderAgent::post()
379	   278	{
380	   279	    m_sse_buffer.clear();
381	   280	    m_terminal_seen = false;
382	   281	    m_busy = true;
383	   282	    ++m_transcript.request_sequence;
384	   283	    m_codec->reset();
385	   284	    ProviderRequest built = m_codec->build(m_transcript, m_config.profile, m_kind);
386	   285	    AgentHttpRequest request;
387	   286	    request.url = m_config.profile.endpoint;
388	   287	    request.headers.push_back(auth_header(m_config.profile, m_config.api_key));
389	   288	    request.headers.insert(request.headers.end(), m_config.profile.headers.begin(), m_config.profile.headers.end());
390	   289	    request.headers.insert(request.headers.end(), built.headers.begin(), built.headers.end());
391	   290	    request.body = built.body.dump();
392	   291	    const std::uint64_t generation = ++m_http_generation;
393	   292	    if (!m_transport->post(std::move(request), [this, generation](AgentHttpEvent event) {
394	   293	            accept_http(generation, std::move(event));
395	   294	        })) {
396	   295	        m_busy = false;
397	   296	        return false;
398	   297	    }
399	   298	    return true;
400	   299	}
