408	   307	void ProviderAgent::parse_sse_frame(const std::string& frame)
409	   308	{
410	   309	    std::string payload;
411	   310	    std::istringstream lines(frame);
412	   311	    std::string line;
413	   312	    while (std::getline(lines, line)) {
414	   313	        if (!line.empty() && line.back() == '\r')
415	   314	            line.pop_back();
416	   315	        if (line.rfind("data:", 0) == 0) {
417	   316	            std::string part = line.substr(5);
418	   317	            if (!part.empty() && part.front() == ' ')
419	   318	                part.erase(part.begin());
420	   319	            if (!payload.empty())
421	   320	                payload += '\n';
422	   321	            payload += part;
423	   322	        }
424	   323	    }
425	   324	    if (payload.empty() || payload == "[DONE]")
426	   325	        return;
427	   326	    for (StreamEvent& event : m_codec->parse(payload))
428	   327	        handle(std::move(event));
429	   328	}
430	   329	
431	   330	void ProviderAgent::handle(StreamEvent event)
432	   331	{
433	   332	    switch (event.kind) {
434	   333	    case StreamEvent::Kind::TextDelta: m_events.push_back(AgentEvent::delta(std::move(event.text))); break;
435	   334	    case StreamEvent::Kind::TurnComplete: finish_response(std::move(event)); break;
436	   335	    case StreamEvent::Kind::Incomplete:
437	   336	        fail(AgentError{"incomplete_response", "The Agent service stopped before finishing its response.", true});
438	   337	        break;
439	   338	    case StreamEvent::Kind::Failed: fail(std::move(event.error)); break;
440	   339	    }
441	   340	}
442	   341	
443	   342	void ProviderAgent::finish_response(StreamEvent event)
444	   343	{
445	   344	    if (m_terminal_seen)
446	   345	        return;
447	   346	    m_terminal_seen = true;
448	   347	    if (m_config.usage_listener && event.usage)
449	   348	        m_config.usage_listener(*event.usage);
450	   349	    m_queued_calls.clear();
451	   350	    m_step_skills.clear();
452	   351	    m_failed_call.clear();
453	   352	    m_transcript.steps.push_back(TurnStep{std::move(event.assistant_turn), {}, {}});
454	   353	    if (event.resend) {
455	   354	        // The provider paused its own turn and resumes it from this one.
456	   355	        constexpr unsigned kPausedTurnLimit = 4;
457	   356	        if (++m_paused_turns > kPausedTurnLimit) {
458	   357	            fail(AgentError{"agent_paused_too_often", "The Agent service kept pausing its response.", true});
459	   358	            return;
460	   359	        }
461	   360	        if (!post())
462	   361	            fail(AgentError{"agent_continuation_failed", "The Agent could not be asked to continue its response.", true});
463	   362	        return;
464	   363	    }
465	   364	    for (ProviderToolCall& call : event.calls)
466	   365	        m_queued_calls.push_back(std::move(call));
467	   366	    if (!next_call())
468	   367	        fail(AgentError{"agent_continuation_failed", "The Agent could not be told the results of its tool calls.", true});
469	   368	}
470	   369	
471	   370	// Hands out the next call of the response, or, once every call has its
472	   371	// result, sends them all back. Whatever the model sent, the next request
473	   372	// never carries a call without its result. False only when that request
474	   373	// could not be sent.
475	   374	bool ProviderAgent::next_call()
476	   375	{
477	   376	    while (!m_queued_calls.empty()) {
478	   377	        const ProviderToolCall item = std::move(m_queued_calls.front());
479	   378	        m_queued_calls.pop_front();
480	   379	        const std::string& call_id = item.call_id;
481	   380	        ToolRequest request{item.name, item.arguments_json};
482	   381	        // The model chose this call before it saw the earlier call fail, so
483	   382	        // it is answered unrun and the model decides again with both results.
484	   383	        if (!call_id.empty() && !m_failed_call.empty()) {
485	   384	            answer_call(call_id, json{{"state", "failed"},
486	   385	                                      {"error", json{{"code", "not_run"},
487	   386	                                                     {"message", "Not run: an earlier call in the same response, " + m_failed_call +
488	   387	                                                                     ", did not succeed. Nothing was queued. Call it again if it is "
489	   388	                                                                     "still needed."}}}});
490	   389	            continue;
491	   390	        }
492	   391	        const auto offered = std::find_if(m_transcript.tools.begin(), m_transcript.tools.end(),
493	   392	                                          [&request](const OfferedTool& tool) { return tool.definition->name == request.tool; });
494	   393	        const bool available = m_kind == RequestKind::Reply && offered != m_transcript.tools.end();
495	   394	        ToolValidationResult validation;
496	   395	        if (available)
497	   396	            validation = ToolRegistry::instance().validate_call(*offered->definition, request.arguments_json);
498	   397	        // A call to no tool of this turn, or with arguments that miss the
499	   398	        // tool's contract, never reaches a card. The model gets the refusal as
500	   399	        // that call's result and may correct it, a bounded number of times
501	   400	        // per turn.
502	   401	        constexpr unsigned kRejectedCallLimit = 2;
503	   402	        if ((!available || !validation.valid()) && m_config.refusal_listener)
504	   403	            m_config.refusal_listener(request.tool, request.arguments_json, available ? validation.error->code : "unknown_tool");
505	   404	        if (!call_id.empty() && m_kind == RequestKind::Reply && (!available || !validation.valid()) &&
506	   405	            m_rejected_calls < kRejectedCallLimit) {
507	   406	            ++m_rejected_calls;
508	   407	            json error = available ?
509	   408	                json{{"code", validation.error->code},
510	   409	                     {"message", validation.error->message +
511	   410	                                     " Nothing was queued. Check the arguments against this tool's parameters and call it again."}} :
512	   411	                json{{"code", "unknown_tool"},
513	   412	                     {"message", "There is no tool named \"" + request.tool + "\" here. Nothing was queued. Use one of the listed tools."}};
514	   413	            answer_call(call_id, json{{"state", "failed"}, {"error", std::move(error)}});
515	   414	            m_failed_call = request.tool + " (" + call_id + ")";
516	   415	            continue;
517	   416	        }
518	   417	        if (call_id.empty() || !available || !validation.valid()) {
519	   418	            fail(AgentError{"malformed_tool_call", "The Agent returned an invalid tool call.", false});
520	   419	            return true;
521	   420	        }
522	   421	        request.arguments_json = std::move(validation.arguments_json);
523	   422	        m_pending_call_id = call_id;
524	   423	        m_pending_tool    = request.tool;
525	   424	        m_waiting_for_tool = true;
526	   425	        AgentToolCall call{call_id, std::move(request), true};
527	   426	        m_events.push_back(AgentEvent::tool_call(std::move(call)));
528	   427	        return true;
529	   428	    }
530	   429	    if (m_transcript.steps.back().results.empty()) {
531	   430	        m_busy = false;
532	   431	        m_events.push_back(AgentEvent::completed());
533	   432	        return true;
534	   433	    }
535	   434	    m_transcript.steps.back().once = skills_to_send(m_step_skills);
536	   435	    m_step_skills.clear();
537	   436	    return post();
538	   437	}
539	   438	
540	   439	void ProviderAgent::parse_available()
541	   440	{
542	   441	    std::deque<QueuedHttpEvent> incoming;
543	   442	    {
544	   443	        std::lock_guard<std::mutex> lock(m_mutex);
545	   444	        incoming.swap(m_http_events);
546	   445	    }
547	   446	    for (QueuedHttpEvent& queued : incoming) {
548	   447	        if (queued.generation != m_http_generation)
549	   448	            continue;
550	   449	        AgentHttpEvent& event = queued.event;
551	   450	        if (event.kind == AgentHttpEvent::Kind::Data) {
552	   451	            m_sse_buffer += event.data;
553	   452	            for (;;) {
554	   453	                const std::size_t lf_pos = m_sse_buffer.find("\n\n");
555	   454	                const std::size_t crlf_pos = m_sse_buffer.find("\r\n\r\n");
556	   455	                const bool crlf_first = crlf_pos != std::string::npos &&
557	   456	                                        (lf_pos == std::string::npos || crlf_pos < lf_pos);
558	   457	                const std::size_t pos = crlf_first ? crlf_pos : lf_pos;
559	   458	                if (pos == std::string::npos)
560	   459	                    break;
561	   460	                const std::string frame = m_sse_buffer.substr(0, pos);
562	   461	                m_sse_buffer.erase(0, pos + (crlf_first ? 4 : 2));
563	   462	                parse_sse_frame(frame);
564	   463	            }
565	   464	        } else if (event.kind == AgentHttpEvent::Kind::Error) {
566	   465	            fail(http_error(event.status, event.error));
567	   466	        } else if (!m_terminal_seen) {
568	   467	            // A valid SSE stream may close immediately after its final data
569	   468	            // line without a trailing blank-line delimiter. Consume that
570	   469	            // complete residual frame before classifying the response.
571	   470	            if (!m_sse_buffer.empty()) {
572	   471	                parse_sse_frame(m_sse_buffer);
573	   472	                m_sse_buffer.clear();
574	   473	            }
575	   474	            if (!m_terminal_seen)
576	   475	                fail(AgentError{"malformed_response", "The Agent service ended before a complete response arrived.", true});
577	   476	        }
578	   477	    }
579	   478	}
580	   479	
581	   480	std::optional<AgentEvent> ProviderAgent::poll()
582	   481	{
583	   482	    parse_available();
584	   483	    if (m_events.empty())
585	   484	        return std::nullopt;
586	   485	    AgentEvent event = std::move(m_events.front());
587	   486	    m_events.pop_front();
588	   487	    return event;
589	   488	}
