591	   490	AgentError ProviderAgent::http_error(unsigned status, const std::string& detail) const
592	   491	{
593	   492	    const std::string& name = m_config.profile.display_name;
594	   493	    if (status == 401 || status == 403)
595	   494	        return {"invalid_credentials", "The " + name + " API key was rejected. Update the Agent configuration and try again.", false};
596	   495	    if (status == 413)
597	   496	        return {"request_too_large", "The request was too large for the " + name + " service.", false};
598	   497	    if (status == 429)
599	   498	        return {"rate_limited", "The " + name + " service is rate limited. Try again shortly.", true};
600	   499	    if (status == 529)
601	   500	        return {"service_overloaded", "The " + name + " service is overloaded. Try again shortly.", true};
602	   501	    if (status >= 500)
603	   502	        return {"service_unavailable", "The " + name + " service is temporarily unavailable.", true};
604	   503	    if (status == 408 || detail.find("timed out") != std::string::npos || detail.find("Timeout") != std::string::npos)
605	   504	        return {"timeout", "The Agent request timed out.", true};
606	   505	    return {"network_error", "The Agent request could not reach the " + name + " service.", true};
607	   506	}
