 22	// The objects-closed rule strict mode needs: every object closes its
 23	// properties and requires all of them. The same rule the Responses codec
 24	// applies, read here on the projected schema.
 25	bool has_closed_required_objects(const json& schema)
 26	{
 27	    if (schema.value("type", json()) == "object") {
 28	        if (schema.value("additionalProperties", json()) != false)
 29	            return false;
 30	        const auto properties = schema.value("properties", json::object());
 31	        const auto required = schema.value("required", json::array());
 32	        for (const auto& property : properties.items())
 33	            if (std::find(required.begin(), required.end(), property.key()) == required.end() ||
 34	                !has_closed_required_objects(property.value()))
 35	                return false;
 36	    }
 37	    return !schema.contains("items") || has_closed_required_objects(schema["items"]);
 38	}
 39	
 40	void project(json& node)
 41	{
 42	    if (node.is_array()) {
 43	        for (json& child : node)
 44	            project(child);
 45	        return;
 46	    }
 47	    if (!node.is_object())
 48	        return;
 49	    static const std::array<const char*, 9> kMoved{"minimum", "maximum",  "multipleOf",    "minLength",    "maxLength",
 50	                                                   "minItems", "maxItems", "minProperties", "maxProperties"};
 51	    std::string moved;
 52	    for (const char* keyword : kMoved) {
 53	        if (!node.contains(keyword))
 54	            continue;
 55	        // minItems of 0 or 1 is the one array constraint strict mode takes.
 56	        if (std::string(keyword) == "minItems" && node[keyword].is_number_integer() && node[keyword].get<long long>() <= 1)
 57	            continue;
 58	        moved += (moved.empty() ? "" : ", ") + std::string(keyword) + " " + node[keyword].dump();
 59	        node.erase(keyword);
 60	    }
 61	    if (!moved.empty()) {
 62	        const std::string description = node.value("description", "");
 63	        node["description"]           = description + (description.empty() ? "(" : " (") + moved + ")";
 64	    }
 65	    for (const char* child : {"properties", "$defs", "definitions"})
 66	        if (node.contains(child) && node[child].is_object())
 67	            for (auto& [key, value] : node[child].items())
 68	                project(value);
 69	    for (const char* child : {"items", "additionalProperties", "anyOf", "oneOf", "allOf", "not"})
 70	        if (node.contains(child))
 71	            project(node[child]);
 72	}
 73	
 74	json tools_json(const std::vector<OfferedTool>& tools)
 75	{
 76	    json items = json::array();
 77	    for (const OfferedTool& tool : tools) {
 78	        json schema = anthropic_strict_schema(tool.definition->input_schema);
 79	        const bool strict = has_closed_required_objects(schema);
 80	        items.push_back(json{{"name", tool.definition->name},
 81	                             {"description", tool.description},
 82	                             {"input_schema", std::move(schema)},
 83	                             {"strict", strict}});
 84	    }
 85	    // Tools render first, so one breakpoint on the last caches them all.
 86	    if (!items.empty())
 87	        items.back()["cache_control"] = ephemeral();
 88	    return items;
 89	}
