 91	// One message of the request as it is built: a role and its blocks, or for
 92	// role "system" its text. Adjacent messages of one role are merged after.
 93	struct Message
 94	{
 95	    std::string role;
 96	    json        blocks{json::array()};
 97	    std::string text; // system only
 98	};
 99	
100	void push(std::vector<Message>& messages, std::string role, json blocks)
101	{
102	    if (blocks.empty())
103	        return;
104	    messages.push_back(Message{std::move(role), std::move(blocks), {}});
105	}
106	
107	void push_system(std::vector<Message>& messages, std::string text)
108	{
109	    if (!text.empty())
110	        messages.push_back(Message{"system", json::array(), std::move(text)});
111	}
112	
113	// The API takes alternating roles, and a mid-conversation system message
114	// only right after a user message, as the last message or before an
115	// assistant one. Adjacent messages of one role become one; a system message
116	// anywhere else becomes a text block of the user message it then joins.
117	// What a message becomes depends only on its neighbours, which a later
118	// request of the same turn keeps, so the history stays append-only.
119	std::vector<Message> normalized(std::vector<Message> messages)
120	{
121	    for (bool changed = true; changed;) {
122	        changed = false;
123	        std::vector<Message> merged;
124	        for (Message& message : messages) {
125	            if (!merged.empty() && merged.back().role == message.role) {
126	                Message& last = merged.back();
127	                if (message.role == "system")
128	                    last.text += "\n\n" + message.text;
129	                else
130	                    last.blocks.insert(last.blocks.end(), message.blocks.begin(), message.blocks.end());
131	                changed = true;
132	                continue;
133	            }
134	            merged.push_back(std::move(message));
135	        }
136	        messages = std::move(merged);
137	        for (std::size_t i = 0; i < messages.size(); ++i) {
138	            if (messages[i].role != "system")
139	                continue;
140	            const bool after_user  = i > 0 && messages[i - 1].role == "user";
141	            const bool then_answer = i + 1 == messages.size() || messages[i + 1].role == "assistant";
142	            if (after_user && then_answer)
143	                continue;
144	            messages[i].role   = "user";
145	            messages[i].blocks = json::array({text_block(messages[i].text)});
146	            messages[i].text.clear();
147	            changed = true;
148	        }
149	    }
150	    return messages;
151	}
152	
153	json message_json(const Message& message)
154	{
155	    if (message.role == "system")
156	        return json{{"role", "system"}, {"content", message.text}};
157	    return json{{"role", message.role}, {"content", message.blocks}};
158	}
159	
160	void push_skills(std::vector<Message>& messages, const std::vector<AgentSkillUse>& skills)
161	{
162	    // Each fired skill: its picture as an image of its own, then its text in
163	    // the app's voice.
164	    for (const AgentSkillUse& skill : skills) {
165	        if (skill.picture)
166	            push(messages, "user", json::array({image_block(skill.picture->mime_type, skill.picture->base64)}));
167	        push_system(messages, skill.text);
168	    }
169	}
