171	std::vector<Message> conversation(const TurnTranscript& transcript, RequestKind kind)
172	{
173	    std::vector<Message> messages;
174	    for (const AgentConversationContext& entry : transcript.opening) {
175	        if (!entry.call_id.empty()) {
176	            // A call from an earlier turn, replayed beside its result.
177	            push(messages, "assistant",
178	                 json::array({json{{"type", "tool_use"}, {"id", entry.call_id}, {"name", entry.tool},
179	                                   {"input", json::parse(entry.arguments_json.empty() ? "{}" : entry.arguments_json)}}}));
180	            push(messages, "user",
181	                 json::array({json{{"type", "tool_result"}, {"tool_use_id", entry.call_id}, {"content", entry.output_json}}}));
182	            continue;
183	        }
184	        if (entry.role == "developer") {
185	            push_system(messages, entry.text);
186	            continue;
187	        }
188	        json blocks = json::array();
189	        if (!entry.text.empty())
190	            blocks.push_back(text_block(entry.text));
191	        if (!entry.issue_context.empty())
192	            blocks.push_back(text_block(tagged_block("print_issue", entry.issue_context)));
193	        push(messages, entry.role, std::move(blocks));
194	    }
195	    if (kind == RequestKind::ConversationTitle) {
196	        // A request may not end on the assistant's turn: that would ask the
197	        // model to continue it.
198	        if (messages.empty() || messages.back().role == "assistant")
199	            push(messages, "user", json::array({text_block("Write the title.")}));
200	        return messages;
201	    }
202	    json content = json::array();
203	    for (const TurnContentPart& part : transcript.user_content) {
204	        switch (part.kind) {
205	        case TurnContentPart::Kind::Text: content.push_back(text_block(part.text)); break;
206	        case TurnContentPart::Kind::Image: content.push_back(image_block(part.mime, part.base64)); break;
207	        case TurnContentPart::Kind::Pdf:
208	            content.push_back(json{{"type", "document"},
209	                                   {"source", json{{"type", "base64"}, {"media_type", "application/pdf"}, {"data", part.base64}}}});
210	            break;
211	        }
212	    }
213	    push(messages, "user", std::move(content));
214	    push_skills(messages, transcript.opening_once);
215	    for (const TurnStep& step : transcript.steps) {
216	        // The response's own content, thinking included, exactly as it came.
217	        push(messages, "assistant", step.assistant_turn);
218	        json results = json::array();
219	        for (const TurnStepResult& result : step.results) {
220	            json block{{"type", "tool_result"}, {"tool_use_id", result.call_id}};
221	            json parts = json::array({text_block(result.output_json)});
222	            if (result.image)
223	                parts.push_back(image_block(result.image->mime_type, result.image->base64));
224	            block["content"] = std::move(parts);
225	            if (result.failed)
226	                block["is_error"] = true;
227	            results.push_back(std::move(block));
228	        }
229	        push(messages, "user", std::move(results));
230	        // Kept on every later request, where it was first sent: removing it
231	        // would change the history before the thinking that followed it.
232	        push_skills(messages, step.once);
233	    }
234	    return messages;
235	}
236	
237	std::uint64_t count(const json& usage, const char* field)
238	{
239	    return usage.contains(field) && usage[field].is_number_unsigned() ? usage[field].get<std::uint64_t>() : 0;
240	}
