251	ProviderRequest AnthropicCodec::build(const TurnTranscript& transcript, const ProviderProfile& profile, RequestKind kind) const
252	{
253	    const bool title = kind == RequestKind::ConversationTitle;
254	    json       messages = json::array();
255	    std::vector<Message> built = normalized(conversation(transcript, kind));
256	    for (const Message& message : built)
257	        messages.push_back(message_json(message));
258	    // A breakpoint on the newest user content caches the turn so far for the
259	    // next request of the same turn.
260	    for (auto it = messages.rbegin(); it != messages.rend(); ++it)
261	        if ((*it)["role"] == "user") {
262	            (*it)["content"].back()["cache_control"] = ephemeral();
263	            break;
264	        }
265	
266	    ProviderRequest request;
267	    request.body = json{{"model", profile.model},
268	                        {"max_tokens", profile.max_tokens},
269	                        {"stream", true},
270	                        {"system", json::array({json{{"type", "text"},
271	                                                     {"text", title ? std::string(kConversationTitleInstructions) : transcript.instructions},
272	                                                     {"cache_control", ephemeral()}}})},
273	                        {"messages", std::move(messages)}};
274	    if (!title && !transcript.tools.empty())
275	        request.body["tools"] = tools_json(transcript.tools);
276	    // An empty system text is not accepted; the loop never builds one for a
277	    // reply (the page supplies the instructions), but a test may.
278	    if (request.body["system"][0]["text"] == "")
279	        request.body.erase("system");
280	    return request;
281	}
