283	void AnthropicCodec::reset()
284	{
285	    m_blocks.clear();
286	    m_usage = AgentUsage{};
287	    m_stop_reason.clear();
288	    m_stop_details = json();
289	}
290	
291	std::vector<StreamEvent> AnthropicCodec::parse(const std::string& payload)
292	{
293	    std::vector<StreamEvent> events;
294	    const auto               failed = [&events](AgentError error) {
295	        StreamEvent event;
296	        event.kind  = StreamEvent::Kind::Failed;
297	        event.error = std::move(error);
298	        events.push_back(std::move(event));
299	    };
300	    const json event = json::parse(payload, nullptr, false);
301	    if (!event.is_object()) {
302	        failed({"malformed_response", "The Agent service returned an unreadable streaming response.", false});
303	        return events;
304	    }
305	    const std::string type = event.value("type", "");
306	    if (type == "message_start") {
307	        const json usage   = event.value("message", json::object()).value("usage", json::object());
308	        m_usage.cached_input   = count(usage, "cache_read_input_tokens");
309	        m_usage.cache_creation = count(usage, "cache_creation_input_tokens");
310	        // Anthropic counts cache reads and writes apart from input_tokens;
311	        // AgentUsage's input is all of it, as OpenAI reports it.
312	        m_usage.input  = count(usage, "input_tokens") + m_usage.cached_input + m_usage.cache_creation;
313	        m_usage.output = count(usage, "output_tokens");
314	    } else if (type == "content_block_start") {
315	        m_blocks[event.value("index", 0)] = Block{event.value("content_block", json::object()), {}};
316	    } else if (type == "content_block_delta") {
317	        const auto found = m_blocks.find(event.value("index", 0));
318	        if (found == m_blocks.end()) {
319	            failed({"malformed_response", "The Agent service streamed a delta for a block it never opened.", false});
320	            return events;
321	        }
322	        Block&            block = found->second;
323	        const json        delta = event.value("delta", json::object());
324	        const std::string kind  = delta.value("type", "");
325	        if (kind == "text_delta") {
326	            const std::string text = delta.value("text", "");
327	            block.content["text"]  = block.content.value("text", "") + text;
328	            StreamEvent out;
329	            out.kind = StreamEvent::Kind::TextDelta;
330	            out.text = text;
331	            events.push_back(std::move(out));
332	        } else if (kind == "input_json_delta") {
333	            block.partial_json += delta.value("partial_json", "");
334	        } else if (kind == "thinking_delta") {
335	            block.content["thinking"] = block.content.value("thinking", "") + delta.value("thinking", "");
336	        } else if (kind == "signature_delta") {
337	            block.content["signature"] = block.content.value("signature", "") + delta.value("signature", "");
338	        }
339	    } else if (type == "content_block_stop") {
340	        const auto found = m_blocks.find(event.value("index", 0));
341	        if (found != m_blocks.end() && found->second.content.value("type", "") == "tool_use") {
342	            const std::string& text  = found->second.partial_json;
343	            const json         input = json::parse(text.empty() ? "{}" : text, nullptr, false);
344	            if (input.is_discarded()) {
345	                failed({"malformed_response", "The Agent service sent a tool call whose arguments are not JSON.", false});
346	                return events;
347	            }
348	            found->second.content["input"] = input;
349	        }
350	    } else if (type == "message_delta") {
351	        const json delta = event.value("delta", json::object());
352	        if (delta.contains("stop_reason") && delta["stop_reason"].is_string())
353	            m_stop_reason = delta["stop_reason"].get<std::string>();
354	        if (delta.contains("stop_details"))
355	            m_stop_details = delta["stop_details"];
356	        const json usage = event.value("usage", json::object());
357	        if (usage.contains("output_tokens"))
358	            m_usage.output = count(usage, "output_tokens");
359	    } else if (type == "message_stop") {
360	        events.push_back(finish());
361	    } else if (type == "error") {
362	        failed({"agent_service_error", "The Agent service could not complete the response.", true});
363	    }
364	    return events;
365	}
366	
367	StreamEvent AnthropicCodec::finish()
368	{
369	    StreamEvent event;
370	    if (m_stop_reason == "max_tokens" || m_stop_reason == "model_context_window_exceeded") {
371	        event.kind = StreamEvent::Kind::Incomplete;
372	        return event;
373	    }
374	    if (m_stop_reason == "refusal") {
375	        event.kind = StreamEvent::Kind::Failed;
376	        std::string category = m_stop_details.is_object() && m_stop_details.value("category", json()).is_string() ?
377	                                   m_stop_details["category"].get<std::string>() : std::string("unspecified");
378	        event.error = {"refusal", "The Agent service declined to answer (" + category + ").", false};
379	        return event;
380	    }
381	    if (m_stop_reason != "end_turn" && m_stop_reason != "tool_use" && m_stop_reason != "stop_sequence" &&
382	        m_stop_reason != "pause_turn") {
383	        event.kind  = StreamEvent::Kind::Failed;
384	        event.error = {"malformed_response", "The Agent service ended its response for a reason this build does not know.", false};
385	        return event;
386	    }
387	    event.kind           = StreamEvent::Kind::TurnComplete;
388	    event.assistant_turn = json::array();
389	    for (auto& [index, block] : m_blocks) {
390	        if (block.content.value("type", "") == "tool_use")
391	            event.calls.push_back({block.content.value("id", ""), block.content.value("name", ""),
392	                                   block.partial_json.empty() ? "{}" : block.partial_json});
393	        event.assistant_turn.push_back(block.content);
394	    }
