  9	
 10	namespace Slic3r::GUI::JusPrin::Agent {
 11	
 12	namespace {
 13	
 14	class OpenAIHttpTransport final : public IAgentHttpTransport
 15	{
 16	public:
 17	    bool post(AgentHttpRequest request, EventFn event) override
 18	    {
 19	        cancel();
 20	        auto state = std::make_shared<State>();
 21	        state->event = std::move(event);
 22	        m_state = state;
 23	
 24	        auto http = Slic3r::Http::post(std::move(request.url));
 25	        // The credential and the codec's own headers, then what every
 26	        // JSON-over-SSE provider is sent.
 27	        for (const AgentHttpHeader& header : request.headers)
 28	            http.header(header.name, header.value);
 29	        http.header("Content-Type", "application/json")
 30	            .header("Accept", "text/event-stream")
 31	            .tls_verify(true)
 32	            .timeout_connect(request.connect_timeout_seconds)
 33	            .timeout_max(request.request_timeout_seconds)
 34	            .size_limit(request.response_size_limit)
 35	            .set_post_body(request.body)
 36	            .on_progress([weak = std::weak_ptr<State>(state)](Slic3r::Http::Progress progress, bool& should_cancel) {
 37	                const auto locked = weak.lock();
 38	                if (!locked)
 39	                    return;
 40	                std::lock_guard<std::mutex> guard(locked->mutex);
 41	                should_cancel = locked->cancelled;
 42	                if (locked->cancelled || progress.buffer.size() <= locked->seen)
 43	                    return;
 44	                std::string delta = progress.buffer.substr(locked->seen);
 45	                locked->seen = progress.buffer.size();
 46	                locked->event(AgentHttpEvent{AgentHttpEvent::Kind::Data, std::move(delta), {}, 0});
 47	            })
 48	            .on_complete([weak = std::weak_ptr<State>(state)](std::string body, unsigned status) {
 49	                const auto locked = weak.lock();
 50	                if (!locked)
 51	                    return;
 52	                std::lock_guard<std::mutex> guard(locked->mutex);
 53	                if (locked->cancelled)
 54	                    return;
 55	                if (body.size() > locked->seen)
 56	                    locked->event(AgentHttpEvent{AgentHttpEvent::Kind::Data, body.substr(locked->seen), {}, status});
 57	                locked->event(AgentHttpEvent{AgentHttpEvent::Kind::Complete, {}, {}, status});
 58	            })
 59	            .on_error([weak = std::weak_ptr<State>(state)](std::string, std::string error, unsigned status) {
 60	                const auto locked = weak.lock();
 61	                if (!locked)
 62	                    return;
 63	                std::lock_guard<std::mutex> guard(locked->mutex);
 64	                if (!locked->cancelled)
 65	                    locked->event(AgentHttpEvent{AgentHttpEvent::Kind::Error, {}, std::move(error), status});
 66	            });
 67	        state->http = http.perform();
 68	        return state->http != nullptr;
 69	    }
 70	
 71	    void cancel() override
 72	    {
 73	        const auto state = std::move(m_state);
 74	        if (!state)
 75	            return;
 76	        Slic3r::Http::Ptr http;
 77	        {
 78	            std::lock_guard<std::mutex> guard(state->mutex);
 79	            state->cancelled = true;
 80	            http = state->http;
 81	        }
 82	        if (http)
 83	            http->cancel();
 84	    }
 85	
 86	private:
 87	    struct State
 88	    {
 89	        std::mutex       mutex;
 90	        EventFn          event;
 91	        Slic3r::Http::Ptr http;
 92	        std::size_t      seen{0};
 93	        bool             cancelled{false};
 94	    };
 95	    std::shared_ptr<State> m_state;
 96	};
 97	
 98	} // namespace
 99	
100	std::unique_ptr<IAgentHttpTransport> make_openai_http_transport()
101	{
102	    return std::make_unique<OpenAIHttpTransport>();
103	}
