 36	struct StopReadsAtExit
 37	{
 38	    // Its own reference: the static behind reads() may be gone first.
 39	    std::shared_ptr<Reads> m_reads = reads();
 40	
 41	    ~StopReadsAtExit()
 42	    {
 43	        m_reads->stopping = true;
 44	        // Curl checks for cancellation about once a second while it waits.
 45	        const auto until = std::chrono::steady_clock::now() + std::chrono::seconds(3);
 46	        while (m_reads->running > 0 && std::chrono::steady_clock::now() < until)
 47	            std::this_thread::sleep_for(std::chrono::milliseconds(10));
 48	    }
