149	    if (preset == nullptr)
150	        return std::nullopt;
151	    const std::string key = host_key(name, preset->config);
152	    const auto        now = HostReadings::Clock::now();
153	    // Constructed after Http's curl state, so destroyed before it.
154	    static StopReadsAtExit stop_at_exit;
155	    if (!reads()->stopping && readings()->begin(key, now)) {
156	        ++reads()->running;
157	        auto reader = std::make_shared<const LaneReader>(preset->config, reads());
158	        std::thread([shared = readings(), in_flight = reads(), key, reader] {
159	            shared->finish(key, reader->read(), HostReadings::Clock::now());
160	            --in_flight->running;
161	        }).detach();
162	    }
163	    return readings()->status(key, now);
164	}
