440	ProjectStateDocument::LoadResult ProjectStateDocument::load(const std::string& json_text)
441	{
442	    json parsed = json::parse(json_text, nullptr, false);
443	    if (parsed.is_discarded() || !parsed.is_object() || !parsed.contains("schemaVersion") ||
444	        !parsed["schemaVersion"].is_number_integer()) {
445	        m_doc = fresh_document();
446	        return LoadResult::Corrupt;
447	    }
448	    const int version = parsed["schemaVersion"].get<int>();
449	    if (version > kSchemaVersion) {
450	        // A newer document must not be edited by an older build that would
451	        // silently drop meaning; treat it like corrupt state.
452	        m_doc = fresh_document();
453	        return LoadResult::Corrupt;
454	    }
455	
456	    // Merge onto the fresh skeleton so documents from older schema versions
457	    // gain any structure they predate while keeping everything they carry.
458	    json result = fresh_document();
459	    for (auto& [key, value] : parsed.items())
460	        result[key] = std::move(value);
461	    result["schemaVersion"] = kSchemaVersion;
462	    if (!parsed.contains("viewedConversationId"))
463	        result["viewedConversationId"] = result.value("activeConversationId", "");
464	    m_doc                   = std::move(result);
465	    return version < kSchemaVersion ? LoadResult::Migrated : LoadResult::Loaded;
466	}
