515	std::vector<ConversationInfo> ProjectStateDocument::conversations() const
516	{
517	    std::vector<ConversationInfo> result;
518	    for (const json& entry : m_doc["conversations"]) {
519	        ConversationInfo info{entry.value("id", ""), entry.value("title", ""), entry.value("createdAt", "")};
520	        info.updated_at = info.created_at;
521	        info.activity_seq = entry.value("seq", std::uint64_t{0});
522	        for (const json& message : entry["messages"]) {
523	            info.updated_at = message.value("createdAt", info.updated_at);
524	            info.activity_seq = message.value("seq", info.activity_seq);
525	            const std::string text = message.value("text", "");
526	            if (!text.empty())
527	                info.preview = text;
528	            else if (message.contains("attachments") && !message["attachments"].empty())
529	                info.preview = "Attachment";
530	        }
531	        // Bound bridge metadata without splitting a UTF-8 code point.
532	        if (info.preview.size() > 512) {
533	            std::size_t end = 512;
534	            while ((static_cast<unsigned char>(info.preview[end]) & 0xc0) == 0x80) --end;
535	            info.preview.resize(end);
536	        }
537	        result.push_back(std::move(info));
538	    }
539	    std::stable_sort(result.begin(), result.end(), [](const auto& a, const auto& b) {
540	        return a.activity_seq > b.activity_seq;
541	    });
542	    return result;
543	}
