658	bool ProjectStateDocument::rename_conversation(const std::string& conversation_id, const std::string& title, bool generated)
659	{
660	    json* conversation = conversation_json(conversation_id);
661	    if (!conversation || (generated && !needs_conversation_title(conversation_id))) return false;
662	    const auto first = title.find_first_not_of(" \t\r\n");
663	    if (first == std::string::npos) return false;
664	    std::string cleaned = title.substr(first, title.find_last_not_of(" \t\r\n") - first + 1);
665	    const auto characters = std::count_if(cleaned.begin(), cleaned.end(), [](unsigned char byte) {
666	        return (byte & 0xc0) != 0x80;
667	    });
668	    if (characters > 120 || cleaned.find_first_of("\r\n") != std::string::npos) return false;
669	    (*conversation)["title"] = std::move(cleaned);
670	    (*conversation)["titleSource"] = generated ? "generated" : "manual";
671	    touch();
672	    return true;
673	}
