699	std::optional<std::vector<std::string>> ProjectStateDocument::delete_conversation(const std::string& conversation_id,
700	                                                                                const std::string& timestamp)
701	{
702	    const json* conversation = conversation_json(conversation_id);
703	    if (!conversation) return std::nullopt;
704	    const std::string inherited_intent = conversation_id == active_conversation_id()
705	        ? setup_intent(conversation_id) : std::string();
706	    std::set<std::string> message_ids;
707	    std::set<std::string> attachment_ids;
708	    for (const json& message : (*conversation)["messages"]) {
709	        message_ids.insert(message.value("id", ""));
710	        for (const auto& id : message.value("attachments", json::array()))
711	            attachment_ids.insert(id.get<std::string>());
712	    }
713	    auto& chats = m_doc["conversations"];
714	    chats.erase(std::remove_if(chats.begin(), chats.end(), [&](const json& entry) {
715	        return entry.value("id", "") == conversation_id;
716	    }), chats.end());
717	    auto& activities = m_doc["toolActivities"];
718	    activities.erase(std::remove_if(activities.begin(), activities.end(), [&](const json& entry) {
719	        return message_ids.count(entry.value("correlationId", "")) != 0;
720	    }), activities.end());
721	    for (const json& chat : chats)
722	        for (const json& message : chat["messages"])
723	            for (const auto& id : message.value("attachments", json::array()))
724	                attachment_ids.erase(id.get<std::string>());
725	    std::vector<std::string> removed_dirs;
726	    auto& attachments = m_doc["attachments"];
727	    attachments.erase(std::remove_if(attachments.begin(), attachments.end(), [&](const json& entry) {
728	        const std::string id = entry.value("id", "");
729	        if (!attachment_ids.count(id) || entry.value("state", "") == "staged") return false;
730	        removed_dirs.push_back("attachments/" + id);
731	        return true;
732	    }), attachments.end());
733	    if (chats.empty() || active_conversation_id() == conversation_id) {
734	        const std::string replacement = create_conversation({}, timestamp);
735	        if (!inherited_intent.empty())
736	            set_setup_intent(replacement, inherited_intent);
737	    }
738	    if (viewed_conversation_id() == conversation_id)
739	        m_doc["viewedConversationId"] = active_conversation_id();
740	    touch();
741	    return removed_dirs;
742	}
